import {app,nativeImage,type BrowserWindow} from 'electron';
import {renderVisual} from '../../apps/desktop/src/sandbox/manager';
import {createServer} from 'node:http';
import {captureVisual as captureCompiledVisual} from '../../apps/desktop/src/sandbox/capture';
import {compileInWorker} from '../../apps/desktop/src/sandbox/compiler-client';
import {writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import type {VisualDefinition} from '@dream/contracts';
import {AssetSchema} from '@dream/footage';
app.commandLine.appendSwitch('force-device-scale-factor','1.5');app.on('window-all-closed',()=>{});
async function captureVisual(definition:VisualDefinition,assets:Parameters<typeof captureCompiledVisual>[1],options:Omit<Parameters<typeof captureCompiledVisual>[2],'compiled'>,signal:AbortSignal){return captureCompiledVisual(definition,assets,{...options,compiled:await compileInWorker(resolve('artifacts/sandbox-acceptance/component-compile.cjs'),definition,signal)},signal);}
async function run(){
 await app.whenReady();try{
  const definition:VisualDefinition={schemaVersion:1,id:'orbital',title:'Orbit test',code:`import React from 'react';import {AbsoluteFill,useCurrentFrame,interpolate} from 'remotion';export default function Scene(){if(typeof window.dream!=='undefined'||typeof require!=='undefined'||typeof process!=='undefined')throw new Error('Privileged bridge leaked');const f=useCurrentFrame();return <AbsoluteFill><svg width={320} height={180}><circle cx={40+f*8} cy={70} r={24} fill='#6d8cff'/><path d='M20 140 Q160 20 300 140' fill='none' stroke='#b888ff' strokeWidth={4}/></svg><div style={{position:'absolute',left:24,top:140,color:'white',fontSize:20,transform:'rotate('+interpolate(f,[0,11],[-4,4])+'deg)'}}>Dream motion</div></AbsoluteFill>}`,parameters:{},parameterSchema:{type:'object'},width:320,height:180,fps:30,durationInFrames:12,seed:8,assetIds:[],transparent:true};
  const options={runtimeDirectory:resolve('apps/desktop/resources/staged/sandbox'),directory:resolve('artifacts/sandbox-acceptance/frames'),testOnly:true};
  const result=await captureVisual(definition,[],options,new AbortController().signal);if(new Set(result.frames.map(f=>f.sha256)).size!==4)throw new Error('Animated test frames did not change.');
  const png=nativeImage.createFromPath(options.directory+'/000000.png');if(png.toBitmap()[3]!==0)throw new Error('Transparent capture lost alpha.');
  const video=AssetSchema.parse({id:'selected-video',filename:'selected-video.mp4',kind:'video',durationSec:.4,width:64,height:64,fps:30,originalPath:resolve('artifacts/sandbox-acceptance/selected-video.mp4'),fingerprint:'fixture',status:'ready'}),videoDirectory=options.directory+'-video';
  await captureVisual({...definition,width:64,height:64,assetIds:[video.id],transparent:false,code:"import React from 'react';import {Html5Video} from 'remotion';export default function Scene({assets}){return <Html5Video src={assets['selected-video']} muted style={{width:64,height:64}}/>;}"},[video],{...options,directory:videoDirectory},new AbortController().signal);
  for(const frame of [0,3,7,11]){const bitmap=nativeImage.createFromPath(videoDirectory+'/'+String(frame).padStart(6,'0')+'.png').toBitmap(),offset=(32*64+32)*4;if(frame<6?bitmap[offset+2]<220||bitmap[offset]>35:bitmap[offset]<220||bitmap[offset+2]>35)throw new Error('Selected video seek captured the wrong source frame: '+frame);}
  let caught=false,reported='';try{await captureVisual({...definition,code:"export default function Scene(){throw new Error('Intentional render failure');}"},[],{...options,directory:options.directory+'-error'},new AbortController().signal);}catch(error){reported=String(error);caught=reported.includes('Intentional render failure');}if(!caught)throw new Error('Runtime failure report mismatch: '+reported);
  const cacheOptions={runtimeDirectory:options.runtimeDirectory,cacheDirectory:resolve('artifacts/sandbox-acceptance/cache'),compilerWorker:resolve('artifacts/sandbox-acceptance/component-compile.cjs')};
  const cachedDefinition={...definition,id:'stable-cache-fixture-'+Date.now()};const first=await renderVisual(cachedDefinition,[],cacheOptions,new AbortController().signal);const second=await renderVisual(cachedDefinition,[],cacheOptions,new AbortController().signal);if(!second.cacheHit||first.manifest.revisionId!==second.manifest.revisionId||second.manifest.frames.length!==12)throw new Error('Immutable visual cache was not reused.');
  const runaway=new AbortController(),cancelAt=setTimeout(()=>runaway.abort(),15000);let terminated=false,enteredLoop=false,cancelError='';const observeRunaway=(_event:unknown,window:BrowserWindow)=>window.webContents.on('page-title-updated',(_event,title)=>{if(title==='runaway-entered'){enteredLoop=true;setTimeout(()=>runaway.abort(),50);}});app.once('browser-window-created',observeRunaway);try{await captureVisual({...definition,code:"export default function Scene(){document.title='runaway-entered';while(true){};return null;}"},[],{...options,directory:options.directory+'-runaway'},runaway.signal);}catch(error){terminated=(error as Error).name==='AbortError';cancelError=String(error);}finally{clearTimeout(cancelAt);app.removeListener('browser-window-created',observeRunaway);}if(!terminated||!enteredLoop)throw new Error('Runaway visual did not terminate on cancellation after entering its loop: '+cancelError);
  let networkRequests=0;const external=createServer((_request,response)=>{networkRequests++;response.end('must not reach');});await new Promise<void>(resolve=>external.listen(0,'127.0.0.1',resolve));const target='http://127.0.0.1:'+(external.address() as {port:number}).port;
  try{await captureVisual({...definition,durationInFrames:1,code:'await fetch('+JSON.stringify(target)+').then(()=>{throw new Error("External network was reachable");},()=>{});'+definition.code},[],{...options,directory:options.directory+'-network'},new AbortController().signal);if(networkRequests)throw new Error('External network access was not denied.');}finally{external.closeAllConnections();await new Promise<void>(resolve=>external.close(()=>resolve()));}
  const report={passed:true,fullSequence:true,cacheReuse:true,networkDenied:true,runawayCanceled:true,selectedVideoFrameTiming:true,displayScaleFactor:1.5,outputPixels:png.getSize(),frames:result.frames,alpha:true,noPrivilegedGlobals:true,runtimeErrors:true};writeFileSync(resolve('artifacts/sandbox-acceptance/report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report));
 }catch(error){console.error(error);process.exitCode=1;}finally{app.exit(process.exitCode?Number(process.exitCode):0);}
}
void run();
